def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    return int(value.total_seconds())

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    return value.isoformat()

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    if not hasattr(self, "_keys") or self._keys is None:
        return []
    return list(self._keys.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(key)

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are provided, return all values
    if not keys:
        # Assume the record stores items in a dict-like attribute `_items`
        return list(self._items.values())

    # Prepare a list of values in insertion order
    items = list(self._items.items())
    values = [v for _, v in items]
    result = []

    for key in keys:
        # If key is an integer, treat it as an index
        if isinstance(key, int):
            if 0 <= key < len(values):
                result.append(values[key])
        else:
            # Otherwise treat it as a dictionary key
            if key in self._items:
                result.append(self._items[key])

    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no keys are specified, return all items
    if not keys:
        return {name: value for name, value in zip(self._keys, self._values)}

    result = {}
    for key in keys:
        # Handle integer indices
        if isinstance(key, int):
            try:
                value = self._values[key]
            except IndexError:
                raise IndexError(f"Index {key} out of bounds")
            name = self._keys[key]
            result[name] = value
        else:
            # Treat as a field name
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Ensure fields is a list of field names
    if isinstance(fields, str):
        fields = [fields]
    elif not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a string or an iterable of field names")

    # Build the namespace for the new class
    namespace = {}
    # Use __slots__ to prevent dynamic attribute creation
    namespace['__slots__'] = tuple(fields)
    # Store the SRID mapping as a class attribute
    namespace['srid_map'] = srid_map

    # Define an __init__ that accepts positional or keyword arguments
    def __init__(self, *args, **kwargs):
        expected = len(fields)
        if len(args) + len(kwargs) != expected:
            raise TypeError(f"{name} expected {expected} arguments, got {len(args)+len(kwargs)}")
        # Assign positional arguments
        for field_name, value in zip(fields, args):
            setattr(self, field_name, value)
        # Assign keyword arguments
        for field_name, value in kwargs.items():
            if field_name not in fields:
                raise TypeError(f"Unexpected keyword argument {field_name!r}")
            setattr(self, field_name, value)

    namespace['__init__'] = __init__

    # Create and return the new subclass of Point
    return type(name, (Point,), namespace)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    nums = []
    for part in parts:
        num = ''.join(ch for ch in part if ch.isdigit())
        if num:
            nums.append(int(num))
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        order = []  # most recent at front

        def make_key(args, kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # move key to front (most recent)
                order.remove(key)
                order.insert(0, key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            order.insert(0, key)
            if len(order) > maxsize:
                # evict the most recently used item
                evict_key = order.pop(0)
                cache.pop(evict_key, None)
            return result

        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        cache = collections.OrderedDict()
        wrapper = None
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(type(v) for v in kwargs.values())
            try:
                result = cache[key]
                cache.move_to_end(key)
                wrapper.hits += 1
                return result
            except KeyError:
                wrapper.misses += 1
                result = func(*args, **kwargs)
                cache[key] = result
                if maxsize > 0 and len(cache) > maxsize:
                    cache.popitem(last=False)
                return result
        wrapper.hits = 0
        wrapper.misses = 0
        def cache_clear():
            cache.clear()
        def cache_info():
            return collections.namedtuple('CacheInfo', ['hits', 'misses', 'maxsize', 'currsize'])(wrapper.hits, wrapper.misses, maxsize, len(cache))
        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        counts = {}
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = args
            if kwargs:
                items = tuple(sorted(kwargs.items()))
                key += items
            if typed:
                new_key = []
                for item in key:
                    if isinstance(item, tuple) and len(item) == 2:
                        k, v = item
                        new_key.append((k, v, type(v)))
                    else:
                        new_key.append((item, type(item)))
                key = tuple(new_key)
            if key in cache:
                counts[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            counts[key] = 1
            if len(cache) > maxsize:
                # evict least frequently used
                min_key = min(counts, key=lambda k: counts[k])
                del cache[min_key]
                del counts[min_key]
            return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('dict is empty')
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
