def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    bins_len = getattr(self, 'bins_len', 0)
    if hasattr(self, 'initial_value'):
        self.bins = [self.initial_value] * bins_len
    else:
        self.bins = self.make_bins()

def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []
    if header is not None:
        lines.append(header)
    for point in self:
        # Expect point to be a tuple (coordinate, value)
        if isinstance(point, tuple) and len(point) == 2:
            coord, value = point
        else:
            # Fallback: try to unpack first two elements
            try:
                coord, value = point[0], point[1]
            except Exception:
                # If point is not iterable, skip it
                continue
        # Convert coordinate to string
        if isinstance(coord, (list, tuple)):
            coord_str = separator.join(str(c) for c in coord)
        else:
            coord_str = str(coord)
        # Convert value to string
        if isinstance(value, (list, tuple)):
            value_str = separator.join(str(v) for v in value)
        else:
            value_str = str(value)
        # Join coordinate and value parts
        line = separator.join([coord_str, value_str])
        lines.append(line)
    return "\n".join(lines)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Direct instance of FillRequest
    if isinstance(seq, FillRequest):
        return True

    # Reject if seq is a Source sequence
    if isinstance(seq, Source):
        return False

    # Try to iterate over seq and look for a FillRequest element
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        return False

    return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(getattr(obj, 'run'))

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the list of resources from the application spec
    manifest = getattr(app.spec, 'manifest', [])
    for resource in manifest:
        # Skip resources that already have a custom observer schema
        if 'observer_schema' in resource:
            continue
        # Build a simple default JSON schema for the resource
        default_schema = {
            'type': 'object',
            'properties': {
                'metadata': {
                    'type': 'object',
                    'properties': {
                        'name': {'type': 'string'},
                        'namespace': {'type': 'string'},
                        'labels': {'type': 'object'},
                        'annotations': {'type': 'object'}
                    },
                    'required': ['name']
                },
                'status': {'type': 'object'}
            },
            'required': ['metadata']
        }
        # Attach the default schema to the resource
        resource['observer_schema'] = default_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Ensure the path exists
    if not os.path.exists(path):
        return False
    # Must be a directory
    if not os.path.isdir(path):
        return False
    # Required OCFL metadata files
    required_files = ['.ocfl_root', '.ocfl_version']
    for fname in required_files:
        if not os.path.exists(os.path.join(path, fname)):
            return False
    # Validate .ocfl_root contains valid JSON
    try:
        with open(os.path.join(path, '.ocfl_root'), 'r') as f:
            json.load(f)
    except Exception:
        return False
    # Validate .ocfl_version contains a positive integer
    try:
        with open(os.path.join(path, '.ocfl_version'), 'r') as f:
            version = f.read().strip()
            if not version.isdigit() or int(version) <= 0:
                return False
    except Exception:
        return False
    return True

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    return '\n'.join(f"{prefix}{entry}" for entry in self.validation_log)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a dictionary
    if not isinstance(inventory, dict):
        raise ArgumentError('inventory', 'Inventory must be a dictionary')

    # Determine the specification version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get('type')
        if isinstance(type_val, str):
            # If a mapping from type to spec version exists, use it
            if hasattr(self, 'type_to_version') and type_val in self.type_to_version:
                spec_version = self.type_to_version[type_val]
        # If type is missing or not a string, fall back to self.spec_version

    # Validate required fields for the determined spec version
    required_fields = getattr(self, 'required_fields', {}).get(spec_version, [])
    for field in required_fields:
        if field not in inventory:
            raise ArgumentError(field,
                f"Missing required field '{field}' for spec version {spec_version}")

    # Validate each field against its specification
    field_specs = getattr(self, 'field_specs', {})
    for key, value in inventory.items():
        if key in field_specs:
            spec = field_specs[key]
            # If the spec defines a type, validate it
            expected_type = spec.get('type')
            if expected_type:
                if isinstance(expected_type, (list, tuple)):
                    # Allow multiple types
                    if not isinstance(value, tuple(expected_type)):
                        raise ArgumentError(key,
                            f"Field '{key}' must be one of types {expected_type}, got {type(value)}")
                else:
                    if not isinstance(value, expected_type):
                        raise ArgumentError(key,
                            f"Field '{key}' must be of type {expected_type.__name__}, got {type(value).__name__}")
            # If the spec defines a custom validator, call it
            validator = spec.get('validator')
            if validator and callable(validator):
                validator(value, key)

    # If all checks pass, return the validated inventory
    return inventory

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def _parse_version(v):
        import re
        parts = re.findall(r'\d+', str(v))
        return tuple(int(p) for p in parts)

    result = {}
    if inventory is None:
        return result

    target = _parse_version(version)

    if isinstance(inventory, dict):
        for logical_path, data in inventory.items():
            if isinstance(data, dict):
                # mapping version -> content_file
                for ver, content_file in data.items():
                    if _parse_version(ver) >= target:
                        result.setdefault(logical_path, set()).add(content_file)
            else:
                # assume iterable of entries
                for entry in data:
                    ver = entry.get('version')
                    if ver and _parse_version(ver) >= target:
                        result.setdefault(logical_path, set()).add(entry.get('content_file'))
    elif isinstance(inventory, list):
        for entry in inventory:
            logical_path = entry.get('logical_path')
            ver = entry.get('version')
            if logical_path and ver and _parse_version(ver) >= target:
                result.setdefault(logical_path, set()).add(entry.get('content_file'))
    else:
        # Unsupported inventory type
        raise TypeError("Unsupported inventory type: %s" % type(inventory))

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if "files" not in fixity:
        raise ValueError("Fixity block missing required 'files' key")

    files = fixity["files"]
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")

    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dictionary")

        if "path" not in entry:
            raise ValueError("File entry missing required 'path' key")

        path = entry["path"]
        if path not in manifest_files:
            raise ValueError(f"File '{path}' referenced in fixity not present in manifest")

        # Optional: ensure hash and size are present
        if "hash" not in entry:
            raise ValueError(f"File entry for '{path}' missing required 'hash' key")
        if "size" not in entry:
            raise ValueError(f"File entry for '{path}' missing required 'size' key")

def add_rendition(self, lang, file_path):
    """Add a rendition for a given language.

    The mapping is stored in ``self.renditions``.  For example::

        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }

    Args:
        lang: Language code for the rendition (e.g. ``"en"``).
        file_path: Path to the rendition file.

    Returns:
        bool: ``True`` if the rendition was added successfully.

    Raises:
        TypeError: If ``lang`` or ``file_path`` is not a string.
        FileNotFoundError: If the file does not exist.
    """
    if not isinstance(lang, str):
        raise TypeError("lang must be a string")
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File {file_path} does not exist")

    if not hasattr(self, "renditions"):
        self.renditions = {}
    self.renditions[lang] = file_path
    return True

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    packages = {}
    with zipfile.ZipFile(zip_path, 'r') as zin:
        # First pass: identify XML files to establish package keys
        for zinfo in zin.infolist():
            if zinfo.is_dir():
                continue
            name = zinfo.filename
            if name.lower().endswith('.xml'):
                base = os.path.splitext(os.path.basename(name))[0]
                packages[base] = {}
        # Second pass: collect all files under their corresponding package
        for zinfo in zin.infolist():
            if zinfo.is_dir():
                continue
            name = zinfo.filename
            base = os.path.splitext(os.path.basename(name))[0]
            if base in packages:
                packages[base][name] = zin.read(name)
    return packages

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = ' ' * indent
    # Helper to format nested objects
    def _format(obj, level):
        if isinstance(obj, (list, tuple)):
            items = [_format(item, level + 2) if hasattr(item, 'pretty') else repr(item) for item in obj]
            return f'{type(obj).__name__}([\n{indent_str}  ' + ',\n'.join(items) + f'\n{indent_str}])'
        if isinstance(obj, dict):
            items = [f'{repr(k)}: {_format(v, level + 2) if hasattr(v, "pretty") else repr(v)}' for k, v in obj.items()]
            return f'{type(obj).__name__}({{\n{indent_str}  ' + ',\n'.join(items) + f'\n{indent_str}}})'
        if hasattr(obj, '__dict__'):
            attrs = []
            for k, v in obj.__dict__.items():
                val = _format(v, level + 2) if hasattr(v, 'pretty') else repr(v)
                if debug:
                    val = f'{val} ({type(v).__name__})'
                attrs.append(f'{k}={val}')
            return f'{obj.__class__.__name__}({", ".join(attrs)})'
        return repr(obj)

    return _format(self, indent)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        from importlib.metadata import version, PackageNotFoundError
        return version(__name__)
    except Exception:
        return "unknown"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    def _get_text(p):
        return getattr(p, 'text', str(p))

    def _get_type(p):
        return getattr(p, 'type', None)

    if style == 'plain':
        return ' '.join(_get_text(p) for p in pieces)

    elif style == 'html':
        parts = []
        for p in pieces:
            txt = _get_text(p)
            cls = _get_type(p)
            if cls:
                parts.append(f'<span class="{cls}">{txt}</span>')
            else:
                parts.append(f'<p>{txt}</p>')
        return ''.join(parts)

    elif style == 'markdown':
        parts = []
        for p in pieces:
            txt = _get_text(p)
            cls = _get_type(p)
            if cls == 'bold':
                parts.append(f'**{txt}**')
            elif cls == 'italic':
                parts.append(f'*{txt}*')
            else:
                parts.append(txt)
        return ' '.join(parts)

    elif style == 'json':
        import json
        return json.dumps([{'text': _get_text(p), 'type': _get_type(p)} for p in pieces])

    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' in pieces:
        return '.'
    else:
        return '+'

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorator(func):
        """Store func in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = func
        return func
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    def _traverse(obj):
        yield obj
        for child in getattr(obj, 'children', []):
            yield from _traverse(child)

    root = getattr(self, 'root', None)
    if root is None:
        return 0, 0

    num_objects = 0
    good_objects = 0
    for obj in _traverse(root):
        num_objects += 1
        valid = True
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    obj.validate()
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Validation failed for object {obj}: {e}")
        if check_digests and valid:
            try:
                if hasattr(obj, 'check_digest'):
                    if not obj.check_digest():
                        valid = False
                        if show_warnings:
                            print(f"Digest check failed for object {obj}")
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Digest check error for object {obj}: {e}")
        if valid:
            good_objects += 1
    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a root inventory to compare against
    if not hasattr(self, "root_inventory") or self.root_inventory is None:
        raise ValueError("Root inventory must be loaded before validating version inventories")

    # Prepare a place to record digests that differ from the root
    self.different_digests = {}

    for vdir in version_dirs:
        # Path to the inventory file for this version
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Missing inventory for version directory '{vdir}'")

        # Load the inventory
        with open(inv_path, "r", encoding="utf-8") as fh:
            try:
                inv = json.load(fh)
            except Exception as exc:
                raise ValueError(f"Failed to parse inventory at '{inv_path}': {exc}")

        # The inventory must be a mapping of content names to digests
        if not isinstance(inv, dict):
            raise ValueError(f"Inventory at '{inv_path}' must be a JSON object (dict)")

        # Verify that all items in this inventory exist in the root inventory
        unknown_items = set(inv) - set(self.root_inventory)
        if unknown_items:
            raise ValueError(
                f"Inventory at '{inv_path}' contains unknown items: {sorted(unknown_items)}"
            )

        # Record any digests that differ from the root inventory
        diffs = [
            name
            for name, digest in inv.items()
            if self.root_inventory.get(name) != digest
        ]
        if diffs:
            self.different_digests[vdir] = diffs

    return self

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if not bug_ids:
        return params
    # Convert bug_ids to a comma‑separated string
    if isinstance(bug_ids, (list, tuple)):
        ids_str = ','.join(str(b) for b in bug_ids)
    else:
        ids_str = str(bug_ids)
    # If 'ids' already present, merge with existing values
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            existing_ids = existing.split(',')
        else:
            existing_ids = [str(existing)]
        ids_str = ','.join(existing_ids + [ids_str])
    params['ids'] = ids_str
    return params

