def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size:
        return 0

    size = size.strip()
    # Separate numeric part and unit
    num_part = ''
    unit_part = ''
    for i, ch in enumerate(size):
        if ch.isdigit() or ch in '.-':
            num_part += ch
        else:
            unit_part = size[i:].strip()
            break

    if not num_part:
        raise ValueError(f"Invalid size format: '{size}'")

    try:
        number = float(num_part)
    except ValueError as exc:
        raise ValueError(f"Invalid numeric value in size: '{size}'") from exc

    unit = unit_part.upper()
    if unit in ('', 'B'):
        multiplier = 1
    elif unit in ('K', 'KB'):
        multiplier = 1000
    elif unit in ('M', 'MB'):
        multiplier = 1000 ** 2
    elif unit in ('G', 'GB'):
        multiplier = 1000 ** 3
    elif unit in ('T', 'TB'):
        multiplier = 1000 ** 4
    elif unit in ('P', 'PB'):
        multiplier = 1000 ** 5
    elif unit in ('E', 'EB'):
        multiplier = 1000 ** 6
    elif unit in ('Z', 'ZB'):
        multiplier = 1000 ** 7
    elif unit in ('Y', 'YB'):
        multiplier = 1000 ** 8
    else:
        raise ValueError(f"Unknown unit '{unit_part}' in size: '{size}'")

    return int(round(number * multiplier))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url

    import re
    # Pattern matches {key} placeholders
    pattern = re.compile(r'\{([^}]+)\}')

    def _replacer(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)

    return pattern.sub(_replacer, url)

def is_none_string(val: any) -> bool:
