def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    return re.sub(r'^["\']|["\']$', '', name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1

    if platform == 1:  # POSIX
        # Regex that matches double-quoted, single-quoted, or unquoted tokens
        pattern = re.compile(r'''(?:"([^"]*)"|'([^']*)'|(\S+))''')
        parts = []
        for m in pattern.finditer(s):
            part = m.group(1) or m.group(2) or m.group(3)
            parts.append(part)
        return parts
    elif platform == 0:  # Windows
        # Use shlex with posix=False to mimic Windows CMD parsing
        return shlex.split(s, posix=False)
    else:
        raise ValueError('Unsupported platform value: %r' % platform)

def addignored(ignored):
