def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    errors = []

    def _replace_env(value):
        import os, re
        if isinstance(value, str):
            return re.sub(r'\$\{([^}]+)\}', lambda m: os.getenv(m.group(1), m.group(0)), value)
        elif isinstance(value, dict):
            return {k: _replace_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_replace_env(v) for v in value]
        else:
            return value

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                content = f.read()
            # Try TOML
            try:
                cfg = toml.loads(content)
            except Exception:
                # Try YAML
                try:
                    cfg = yaml.safe_load(content)
                except Exception:
                    # Try JSON
                    try:
                        cfg = json.loads(content)
                    except Exception as e:
                        raise ValueError(f"Unsupported format for {fname}") from e
            if not isinstance(cfg, dict):
                raise ValueError(f"Configuration in {fname} is not a dict")
            if resolve_env:
                cfg = _replace_env(cfg)
            if overrides:
                cfg.update(overrides)
            configs[fname] = cfg
        except Exception as e:
            exc_info = sys.exc_info()
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=exc_info
            )
            errors.append(record)
    return configs, errors

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        return self.scale

    # Ensure other is numeric
    try:
        new_scale = float(other)
    except Exception:
        raise TypeError("other must be a numeric value")

    # Check current scale
    if self.scale is None or self.scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    factor = new_scale / self.scale

    # Rescale last coordinate in data
    if hasattr(self, 'data') and self.data is not None:
        # Assume data is a 2D array
        try:
            self.data[:, -1] *= factor
        except Exception:
            pass

    # Rescale errors
    if hasattr(self, 'errors') and self.errors is not None:
        # If errors is a dict mapping field names to arrays
        if isinstance(self.errors, dict):
            last_field = self.fields[-1] if hasattr(self, 'fields') else None
            if last_field and last_field in self.errors:
                try:
                    self.errors[last_field] *= factor
                except Exception:
                    pass
        # If errors is a list or tuple of arrays
        elif isinstance(self.errors, (list, tuple)):
            try:
                self.errors[-1] *= factor
            except Exception:
                pass
        # If errors is a 2D array aligned with data
        else:
            try:
                self.errors[:, -1] *= factor
            except Exception:
                pass

    # Update scale
    self.scale = new_scale
    return self

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Determine the class of the candidate
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # If iface is a class, check subclass relationship first
    if isinstance(iface, type):
        if issubclass(candidate_cls, iface):
            return True

    # Gather the attributes that define the interface
    required = []
    for name in dir(iface):
        if name.startswith('__') and name.endswith('__'):
            continue
        required.append(name)

    # Check that candidate has all required attributes
    missing = [name for name in required if not hasattr(candidate, name)]
    if missing:
        if tentative:
            return False
        raise TypeError(f"Candidate {candidate!r} does not provide {iface!r}: missing {missing}")

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Helper to compute the most derived metaclass of two metaclasses
    def _most_derived_meta(meta1, meta2):
        if issubclass(meta1, meta2):
            return meta1
        if issubclass(meta2, meta1):
            return meta2
        raise TypeError(f"metaclasses {meta1.__name__} and {meta2.__name__} conflict")

    # If an explicit metaclass is supplied, validate it
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"__metaclass__ must be a class, got {explicit_mc!r}")
        if not bases:
            return explicit_mc
        # Determine the metaclass implied by the bases
        base_meta = type(bases[0])
        for base in bases[1:]:
            base_meta = _most_derived_meta(base_meta, type(base))
        # The explicit metaclass must be a subclass of the base-derived metaclass
        if not issubclass(explicit_mc, base_meta):
            raise TypeError(
                f"__metaclass__ {explicit_mc.__name__} is not a subclass of {base_meta.__name__}"
            )
        return explicit_mc

    # No explicit metaclass: derive from bases
    if not bases:
        return type
    base_meta = type(bases[0])
    for base in bases[1:]:
        base_meta = _most_derived_meta(base_meta, type(base))
    return base_meta

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    node = self._tail[2]
