def isoparse(self, dt_str):
    """Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    Supports the date and time formats described in the docstring, including
    ISO week dates, fractional seconds, and time zone offsets.  Unspecified
    components default to their lowest value.  Midnight may be represented
    as ``00:00`` or ``24:00``; the latter is converted to the next day.
    """
    s = dt_str.strip()
    # Split date and time parts
    if 'T' in s:
        date_part, rest = s.split('T', 1)
    else:
        date_part, rest = s, ''
    # ---------- Parse date ----------
    year = month = day = 1
    if 'W' in date_part or 'w' in date_part:
        # ISO week date: YYYY-Www or YYYYWww, optionally with day
        m = re.match(r'(\d{4})[Ww]?(\d{2})(?:[Ww]?(\d))?$', date_part)
        if not m:
            raise ValueError(f"Invalid ISO week date: {date_part}")
        year = int(m.group(1))
        week = int(m.group(2))
        weekday = int(m.group(3)) if m.group(3) else 1
        try:
            d = datetime.date.fromisocalendar(year, week, weekday)
        except AttributeError:
            # Fallback for Python < 3.8
            d = datetime.date(year, 1, 4) + datetime.timedelta(weeks=week-1, days=weekday-1)
        year, month, day = d.year, d.month, d.day
    else:
        # Regular date: YYYY, YYYYMM, YYYYMMDD
        clean = re.sub(r'[-]', '', date_part)
        if len(clean) == 4:
            year = int(clean)
            month = 1
            day = 1
        elif len(clean) == 6:
            year = int(clean[:4])
            month = int(clean[4:6])
            day = 1
        elif len(clean) == 8:
            year = int(clean[:4])
            month = int(clean[4:6])
            day = int(clean[6:8])
        else:
            raise ValueError(f"Invalid ISO date: {date_part}")
    # ---------- Parse time and timezone ----------
    hour = minute = second = microsecond = 0
    tzinfo = None
    if rest:
        # Separate timezone
        tz_match = re.search(r'(Z|[+-]\d{2}(:?\d{2})?)$', rest)
        if tz_match:
            tz_str = tz_match.group(1)
            time_part = rest[:tz_match.start()]
        else:
            tz_str = ''
            time_part = rest
        # Parse time part
        if time_part:
            time_part = time_part.replace(',', '.')
            parts = time_part.split(':')
            if len(parts) == 1:
                # hh, hhmm, hhmmss[.frac]
                p = parts[0]
                if len(p) == 2:
                    hour = int(p)
                elif len(p) == 4:
                    hour = int(p[:2])
                    minute = int(p[2:])
                elif len(p) == 6 or len(p) > 6:
                    hour = int(p[:2])
                    minute = int(p[2:4])
                    sec_part = p[4:]
                    if '.' in sec_part:
                        sec, frac = sec_part.split('.', 1)
                        second = int(sec)
                        microsecond = int((frac + '000000')[:6])
                    else:
                        second = int(sec_part)
                else:
                    raise ValueError(f"Invalid time format: {time_part}")
            elif len(parts) == 2:
                hour = int(parts[0])
                minute = int(parts[1])
            elif len(parts) == 3:
                hour = int(parts[0])
                minute = int(parts[1])
                sec_part = parts[2]
                if '.' in sec_part:
                    sec, frac = sec_part.split('.', 1)
                    second = int(sec)
                    microsecond = int((frac + '000000')[:6])
                else:
                    second = int(sec_part)
            else:
                raise ValueError(f"Invalid time format: {time_part}")
        # Handle midnight 24:00
        if hour == 24 and minute == 0 and second == 0:
            hour = 0
            dt_date = datetime.date(year, month, day) + datetime.timedelta(days=1)
            year, month, day = dt_date.year, dt_date.month, dt_date.day
        # Parse timezone
        if tz_str:
            if tz_str == 'Z':
                tzinfo = tzutc()
            else:
                sign = 1 if tz_str[0] == '+' else -1
                tz_body = tz_str[1:]
                if ':' in tz_body:
                    h, m = tz_body.split(':')
                else:
                    if len(tz_body) == 4:
                        h = tz_body[:2]
                        m = tz_body[2:]
                    else:
                        h = tz_body
                        m = '0'
                offset = sign * (int(h) * 3600 + int(m) * 60)
                tzinfo = tzoffset(None, offset)
    return datetime.datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tzinfo)

# Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    # Matrix requests are typically sent to URLs starting with /_matrix/
    # and use JSON content type. We also check for the X-Matrix-Request header.
    path = getattr(request, "path", getattr(request, "path_info", ""))
    if path.startswith("/_matrix/"):
        return True
    content_type = request.META.get("CONTENT_TYPE", "")
    if content_type.lower().startswith("application/json"):
        return True
    if request.META.get("HTTP_X_MATRIX_REQUEST"):
        return True
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if dt.tzinfo is None:
        # Assume naive datetimes are in UTC
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    # Convert to UTC and format
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    # Matches URLs starting with http://, https://, or www.
    url_pattern = re.compile(r'(?P<url>(?:https?://|www\.)[^\s]+)')
    def replace(match):
        url = match.group('url')
        href = url
        # Ensure the href has a scheme
        if not href.startswith(('http://', 'https://')):
            href = 'http://' + href
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'
    return url_pattern.sub(replace, text)

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if scheme not in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = urllib.request.Request(url, method='HEAD')
    try:
        with urllib.request.urlopen(req) as resp:
            if hasattr(resp, 'status') and resp.status != 200 and scheme not in ('ftp', 'ftps'):
                return None
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    if len(tag) > 30:
        return False
    allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-")
    if not all(c in allowed for c in tag):
        return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        key = child.tag
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if document_path is None:
        document_path = "/.well-known/nodeinfo/1.0.json"
    if not document_path.startswith("/"):
        document_path = "/" + document_path
    href = url.rstrip("/") + document_path
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Parse the XML document if it is a string
    if isinstance(doc, str):
        try:
            root = etree.fromstring(doc)
        except Exception as e:
            raise ValueError(f"Invalid XML document: {e}")
    else:
        root = doc

    # Parse the signature element if it is a string
    if isinstance(signature, str):
        try:
            sig_node = etree.fromstring(signature)
        except Exception as e:
            raise ValueError(f"Invalid signature XML: {e}")
    else:
        sig_node = signature

    # Create a signature context and load the public key
    ctx = xmlsec.SignatureContext()
    try:
        key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
    except Exception as e:
        raise ValueError(f"Unable to load public key: {e}")
    ctx.key = key

    # Verify the signature
    try:
        ctx.verify(sig_node)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception as e:
        # Any other exception is treated as a verification failure
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    import xml.etree.ElementTree as ET
    try:
        data = json.loads(document)
    except Exception:
        root = ET.fromstring(document)
        subject = None
        aliases = []
        links = []
        for child in root:
            tag = child.tag
            if tag.endswith('Subject'):
                subject = child.text
            elif tag.endswith('Alias'):
                aliases.append(child.text)
            elif tag.endswith('Link'):
                rel = child.attrib.get('rel')
                type_ = child.attrib.get('type')
                href = child.attrib.get('href')
                template = child.attrib.get('template')
                link_dict = {'rel': rel}
                if type_:
                    link_dict['type'] = type_
                if href:
                    link_dict['href'] = href
                if template:
                    link_dict['template'] = template
                links.append(link_dict)
        data = {'subject': subject, 'aliases': aliases, 'links': links}
    hcard_url = None
    profile_url = None
    for link in data.get('links', []):
        if link.get('rel') == 'hcard':
            hcard_url = link.get('href')
        if link.get('rel') == 'profile':
            profile_url = link.get('href')
    data['hcard_url'] = hcard_url
    data['profile_url'] = profile_url
    return data

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Normalize the handle
        if handle.startswith("acct:"):
            handle = handle[5:]
        if "@" not in handle:
            return None
        host = handle.split("@")[1]
        url = "https://{}/.well-known/webfinger?resource=acct:{}".format(host, quote(handle))
        with closing(urllib2.urlopen(url)) as page:
            return page.read()
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    file_names = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if fname.endswith(spec_option):
                    file_names.append(os.path.join(directory, fname))
        except OSError:
            continue
    return sorted(file_names)

