        # Deprecated option name : new option name
        'old_option1': 'new_option1',
        'old_option2': 'new_option2',
        # Add additional mappings here
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Mapping of deprecated argument names to their replacements.
    # This should be defined on the instance (e.g., self.deprecated_args).
    deprecated_map = getattr(self, 'deprecated_args', {})
    for old_arg, new_arg in deprecated_map.items():
        if old_arg in cli_args:
            print(f"Warning: '{old_arg}' is deprecated, use '{new_arg}' instead.")
        if old_arg in answer_file_args:
            print(f"Warning: '{old_arg}' is deprecated in answer file, use '{new_arg}' instead.")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        return self._specs[command_name][argument_name]
    except KeyError:
        return None

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'required_args', [])
    for key in required:
        if key not in args or args[key] is None:
            raise ValueError(f"Missing required argument: {key}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    # Ensure args is a mapping for lookup
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}
    for opt in options_spec:
        # Support both dicts and objects with attributes
        name = getattr(opt, 'name', None) or opt.get('name')
        if not name:
            continue
        cond = getattr(opt, 'required_when', None) or opt.get('required_when')
        if cond is None:
            continue
        matched = False
        try:
            if callable(cond):
                matched = bool(cond(args))
            elif isinstance(cond, str):
                # Treat string as key in args
                matched = bool(args.get(cond))
            elif isinstance(cond, dict):
                # Dict may map command names to conditions
                subcond = cond.get(command_name, cond.get('default'))
                if subcond is None:
                    matched = False
                elif callable(subcond):
                    matched = bool(subcond(args))
                elif isinstance(subcond, str):
                    matched = bool(args.get(subcond))
                else:
                    matched = bool(subcond)
            else:
                matched = bool(cond)
        except Exception:
            matched = False
        if matched:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        # Get the expected maximum length for this argument, if any
        expected_len = arg_defs.get(arg_name, {}).get('length')
        if expected_len is None:
            # No length constraint defined; skip this argument
            continue
        if value is None:
            # None values are considered acceptable regardless of length
            continue
        try:
            actual_len = len(value)
        except TypeError:
            raise TypeError(
                f"Argument '{arg_name}' has no length (value: {value!r})"
            )
        if actual_len > expected_len:
            raise ValueError(
                f"Argument '{arg_name}' length {actual_len} exceeds "
                f"maximum allowed {expected_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        # Locate the argument definition
        if isinstance(arg_defs, dict):
            arg_def = arg_defs.get(arg_name)
        else:  # list of dicts
            arg_def = None
            for item in arg_defs:
                if isinstance(item, dict) and arg_name in item:
                    arg_def = item[arg_name]
                    break
        if not arg_def:
            continue
        choices = arg_def.get('choices')
        if not choices:
            continue
        # Validate the value(s)
        if isinstance(value, (list, tuple)):
            for v in value:
                if v not in choices:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {v}. "
                        f"Expected one of {choices}."
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value}. "
                    f"Expected one of {choices}."
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    if not hasattr(args, "__iter__"):
        raise TypeError("args must be an iterable")
    for arg in args:
        # If arg is a tuple of (value, min, max)
        if isinstance(arg, tuple) and len(arg) == 3:
            value, min_val, max_val = arg
        else:
            value = arg
            min_val = getattr(self, "min", None)
            max_val = getattr(self, "max", None)
        if min_val is not None and value < min_val:
            raise ValueError(f"Argument {value} is less than minimum {min_val}")
        if max_val is not None and value > max_val:
            raise ValueError(f"Argument {value} is greater than maximum {max_val}")
    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Resolve the underlying Python type
    base_type = spec_option.get('type', str)
    if isinstance(base_type, str):
        base_type = {
            'int': int,
            'float': float,
            'bool': lambda v: v.lower() in ('true', '1', 'yes', 'on'),
            'str': str,
        }.get(base_type, str)

    # Build a parser function that will be used as the argparse type
    def parser(value):
        try:
            val = base_type(value)
        except Exception as exc:
            raise ValueError(f"Invalid value for {option_name!r}: {value!r}") from exc

        # Validate against allowed choices if provided
        if 'choices' in spec_option:
            if val not in spec_option['choices']:
                raise ValueError(
                    f"Value for {option_name!r} must be one of {spec_option['choices']!r}"
                )

        # Run a custom validator if supplied
        if 'validator' in spec_option:
            validator = spec_option['validator']
            if not validator(val):
                raise ValueError(
                    f"Custom validation failed for {option_name!r} with value {value!r}"
                )

        return val

    # Return the parser as the complex type
    return parser

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    # Known control arguments that should not be written to the spec
    known_control = {
        'destroy', 'cleanup', 'action', 'subcommand',
        'matrix', 'list', 'login', 'verbose', 'debug'
    }
    for key, value in args.items():
        if key in known_control:
            control_args[key] = value
        else:
            nested_args[key] = value
    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict
    # If a single dict is provided, treat it as a list of one dict
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    for item in extra_vars:
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, (list, tuple)) and len(item) == 2:
            key, value = item
            vars_dict[key] = value
        else:
            raise ValueError("Each extra_var must be a dict or a key-value pair")
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the option definitions for the given parser
    options = getattr(self, "options", {}).get(parser_name, {})
    if not options:
        return values_dict

    for name, opt in options.items():
        if name in values_dict:
            try:
                # Convert the string value to the expected type
                values_dict[name] = opt.convert(values_dict[name])
            except Exception:
                # If conversion fails, keep the original value
                pass
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Find the plugin spec file (yaml or json)
    spec_file = None
    for fname in ('plugin.yaml', 'plugin.yml', 'plugin.json'):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_file = path
            break
    if not spec_file:
        return {}

    # Load the spec file
    with open(spec_file, 'r', encoding='utf-8') as f:
        if spec_file.endswith('.json'):
            data = json.load(f)
        else:
            data = yaml.safe_load(f)

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = getattr(self, 'config_env_var', 'CONFIG_PATH')
    if env_var not in os.environ:
        os.environ[env_var] = str(self.config_path)
